+static gint
+gst_audio_meta_compare_offsets (gconstpointer a, gconstpointer b, gpointer data)
+{
+  gsize x = *(const gsize *) a;
+  gsize y = *(const gsize *) b;
+
+  if (x < y)
+    return -1;
+  if (x > y)
+    return 1;
+  return 0;
